  const candidateApprovalId=benchmarkField(candidate,'approval_id');
  if(!candidateArtifactDigest||!candidateManifestDigest||!candidateDatasetDigest||!candidateApprovalId)throw Object.assign(new Error('LORA_BENCHMARK_PROVENANCE_REQUIRED'),{code:'LORA_BENCHMARK_PROVENANCE_REQUIRED'});
  if(candidateArtifactDigest!==checked.digest)throw Object.assign(new Error('LORA_BENCHMARK_ARTIFACT_MISMATCH'),{code:'LORA_BENCHMARK_ARTIFACT_MISMATCH'});
